package com.qualitypilot.campaignlab.execution;
import jakarta.persistence.*; import java.time.Instant;
@Entity public class CampaignRun{@Id private String id;@Column(name="plan_id")private String planId;@Column(name="audience_calculation_id")private Long audienceCalculationId;@Column(name="audience_batch")private int audienceBatch;@Enumerated(EnumType.STRING)private RunStatus status;@Column(name="total_users")private int totalUsers;@Column(name="started_at")private Instant startedAt;protected CampaignRun(){}public CampaignRun(String id,String planId,Long calculationId,int batch,int total,Instant now){this.id=id;this.planId=planId;audienceCalculationId=calculationId;audienceBatch=batch;totalUsers=total;startedAt=now;status=RunStatus.RUNNING;}public String getId(){return id;}public String getPlanId(){return planId;}public Long getAudienceCalculationId(){return audienceCalculationId;}public int getAudienceBatch(){return audienceBatch;}public RunStatus getStatus(){return status;}public int getTotalUsers(){return totalUsers;}public Instant getStartedAt(){return startedAt;}public void finish(boolean waiting){status=waiting?RunStatus.WAITING:RunStatus.SUCCEEDED;}}
